const SECOND={
 quiet:['散步走到一半，雨音想再去一条支路，阿澈却想早点坐下。你们得决定把共同路线缩短，还是改变相处方式。','茶会开场时，雨音只准备了一件小事，阿澈却有很多见闻。三个人不能都按原先设想占用同样长的发言时间。','分头探索以后，阿澈走得很远，雨音却只坐在入口。交换见闻时，不能用谁经历得更多决定谁先被听见。'],
 workshop:['低负担体验角在旧设备上流畅，在另一台上台阶却看不清。零点想先处理可用性，弥生担心删去的细节再也不会回来。','过程墙里有一张草图的合作者收回展示许可。撤下它之后，整段试错过程不再完整，不能用另一个人的记录填补。','自由路线试展时有人从出口进来，错过说明。你们需要选择只修入口标记，还是重新调整分岔与展品的位置。'],
 gathering:['猜词轮到不爱画画的人。简化成只说一个词可以完成这一轮，但会放弃原来想试的合作画法。','歌单轮到一首大家都不熟悉的长曲。凛想完整听完，阿澈担心最后的人没有时间选歌。','不看攻略的路线遇到一个机关。阿澈知道可能的解法，也想保留大家自己找路的体验；继续尝试会挤掉原定的休息。'],
 letters:['限定时长的同行到一半，小满还有一件很想讲的事，雨音却已经到了答应结束的时间。延长必须重新询问，按时结束也会留下没讲完的部分。','允许改期的卡片第一次需要改动。新的空闲时段与另一份约定相邻，卡片上的愿望得缩小才能真正做到。','异步近况里，有人读完很久仍没能回信。雨音希望不催，小满却想知道对方到底有没有看见。两种需要都是真的。'],
 paths:['声音路线的回信说某段背景太吵。凛喜欢那段节奏，零点则希望给声音敏感的人一个明确的绕行办法。','小路记录里的捷径在另一次访问时关闭了。你们可以先删掉未经确认的部分，也可以把卡片改成有待验证的旅行笔记。','设备入口提示得到两条相反反馈。零点能复现其中一个，凛的设备却没有同样的问题，这次不能替没试过的设备作保证。'],
 renewal:['重新布置的小角落里有一件共同物品。小满想保留，弥生想让新的用途有更多空间。移动它不等于否定旧记忆，留下也不必代表邀请谁回来。','整理记录时，有一页同时写着快乐和不舒服。小满不想只保留好看的部分，弥生也不希望整理又变成整晚重读过去。','新作品开始像旧设计里的一个角落。弥生想另开一条路线，小满觉得相似也可以拥有新的意义。你们得决定这次究竟要完成什么。'],
};
const CONTINUE={
 quiet:['共同路线确实缩短了，你们只走完最想停留的那一处。茶会与更远的见闻没有被混进这次完成记录。','你们改成先各留一段独处，再回到同一张椅子旁。共同停留更短，每个人却真正拥有了能选择的余地。','你们各自过完一小段晚上，回来交换一件小事。有人走远，有人留在入口，没有统一的出勤表。'],
 workshop:['试展只修完了最关键的可用性问题，未展示的草稿与未验证的入口被清楚标成下一版。','你们重新排过说明与展品，展示的重点改变了。留下来的不是原版的全部承诺，而是一套各方重新确认的小展。','零点与弥生分别验证各自的部分，再把能确认的结果拼在一起。仍有一段没法互相验证，被明确留白。'],
 gathering:['规则被缩到能完成的一轮，最后的人真的轮到了。原定的复杂玩法留待有余力时重新邀请。','你们重排了节目的先后和长度，有人接受缩短，也有人选择只旁听。主持工作没有自动退回阿澈与凛。','大家分组完成了不同的小局，再交换各自的趣事。没有要求每个人参加每一段，谢幕也不按在线时长发奖。'],
 letters:['这次只兑现了约定中最重要的一部分，没讲完的内容被写成另一次需要重新回答的邀请。','卡片上的时间与方式被当面改过。原来的等待仍被承认，新约也没有占用别人的承诺。','你们分别写下自己这段日子的近况，再交换愿意分享的部分。没有同时在线的几晚也拥有各自的生活。'],
 paths:['路线卡只留下经过复核的短段，绕行与未确认区域标得很清楚。它更短，也更诚实。','卡片重新按不同偏好排列，原来的必经点变成可选入口。作者喜欢什么与访客需要什么都有了位置。','两位朋友分别按自己的设备与偏好验证，再并排留下结果。不同结论没有被强行平均成一个万能答案。'],
 renewal:['这次只调整一个小角落，其他记录与物品先保存。新的用途已经能使用，也没有假装全部放下。','你们把旧版单独封存，按现在的许可另做一版。改变经过讨论，不承担强行和解或复合的含义。','两个人分别做了自己的新版本，再选择愿意互相分享的一段。旧物与新作不必被整理成同一个答案。'],
};
const CLOSE={
 quiet:['停在这里的一个好晚上','下一张仍可留白的邀请','各自带回去的小事'],workshop:['小展认真关门以后','另起一页的试展单','并排保存的两个版本'],gathering:['轮到每个人的谢幕','下一次换谁发起','散场后各自的歌单'],letters:['这一份约定已经回应','下一张需要重新回答的卡','没有统一封面的来信'],paths:['这张短路线卡的终点','尚待同行验证的一条路','不同设备上的旅行页'],renewal:['现在可以用的小角落','新用途的下一次询问','分别保留的旧版与新稿'],
};
export function themeSecond(t,root){return SECOND[t.id][root];}
export function themeContinuation(t,middle){return CONTINUE[t.id][middle];}
export function themeRoute(t,choices){if(choices.length!==3)return null;const [root,middle,end]=choices;return {key:[t.id,...choices].join(':'),theme:t.id,title:CLOSE[t.id][end],text:`${t.plans[root]}。${CONTINUE[t.id][middle]} `+['你们把这一阶段正式收好，下一次还要重新确认，完成没有变成持续待命。','你们写了一份更小的续篇邀请，它尚未等于任何人答应参加，原来的阶段已经结束。','你们各自保存愿意留下的版本，没有统一合照，也没有要求谁交出私人记录。'][end]};}
export function validThemeRoutes(legacy,themes){return Array.isArray(legacy.themeRoutes)&&legacy.themeRoutes.length<=162&&new Set(legacy.themeRoutes).size===legacy.themeRoutes.length&&legacy.themeRoutes.every(key=>{if(typeof key!=='string')return false;const [id,...choices]=key.split(':');return choices.length===3&&choices.every(x=>['0','1','2'].includes(x))&&themes.some(t=>t.id===id)&&legacy.themesCompleted.includes(id);});}
